71	    /**
72	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
73	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
74	     * and a dotted domain (e.g. {@code not-an-email}).
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
77	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
78	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
79	
80	    /**
81	     * Disposable email domains that are not allowed for an owner. An email whose domain (the part
82	     * after the '@', compared case-insensitively) is listed here is rejected with 400 Bad Request.
83	     */
84	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
85	        "mailinator.com",
86	        "tempmail.com",
87	        "guerrillamail.com");
88	
89	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
90	    private static final String DEFAULT_COUNTRY_CODE = "61";
91	
92	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
93	    private static final int MAX_OWNERS_PER_CITY = 50;
94	
95	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
96	    private static final int MAX_OWNERS_PER_DAY = 100;
97	
98	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
99	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
100	
101	    /** Fixed public-holiday calendar: a registration date landing on any of these is rolled forward past it. */
102	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
103	        LocalDate.of(2026, 1, 1),
104	        LocalDate.of(2026, 1, 26),
105	        LocalDate.of(2026, 4, 25),
106	        LocalDate.of(2026, 12, 25),
107	        LocalDate.of(2026, 12, 28));
108	
109	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
110	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
111	
112	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
113	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
114	
115	    /**
116	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
117	     * is listed here must carry exactly the required number of national digits, otherwise it is
118	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
119	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
120	     */
121	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
122	        "61", 9,
123	        "1", 10);
124	
125	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
126	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
127	        "ST", "STREET",
128	        "RD", "ROAD",
129	        "AVE", "AVENUE");
