131	    /** A well-formed postcode: exactly four digits. */
132	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
133	
134	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
135	    private static final Map<String, String> CITY_REGION = Map.of(
136	        "Sydney", "NSW",
137	        "Melbourne", "VIC",
138	        "Brisbane", "QLD");
