141	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
142	        "NSW", new int[] {2000, 2099},
143	        "VIC", new int[] {3000, 3099},
144	        "QLD", new int[] {4000, 4099});
