147	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
148	
149	    /** Request header carrying the client-supplied idempotency key for a create. */
150	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
