179	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
180	        Collection<Owner> owners;
181	        if (lastName != null) {
182	            owners = this.clinicService.findOwnerByLastName(lastName);
183	        } else {
184	            owners = this.clinicService.findAllOwners();
185	        }
186	        if (owners.isEmpty()) {
187	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
188	        }
189	        owners.forEach(this::populateHouseholdSize);
190	        List<OwnerDto> ownerDtos = new ArrayList<>();
191	        for (Owner owner : owners) {
192	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
193	            applyHouseholdMembershipCap(owner, ownerDto);
194	            ownerDtos.add(ownerDto);
195	        }
196	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
197	    }
