212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
215	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen, return the
216	        // originally created owner with 200 instead of creating (and duplicate-checking) a new one.
217	        String idempotencyKey = currentIdempotencyKey();
218	        if (idempotencyKey != null) {
219	            Integer existingId = idempotencyKeyToOwnerId.get(idempotencyKey);
220	            if (existingId != null) {
221	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
222	                if (existingOwner != null) {
223	                    populateHouseholdSize(existingOwner);
224	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
225	                }
226	            }
227	        }
228	        List<String> missingFields = new ArrayList<>();
229	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
230	            missingFields.add("firstName");
231	        }
232	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
233	            missingFields.add("lastName");
234	        }
235	        // Normalize each supplied address form up front. The structured fields are preferred when
236	        // present; the flat 'address' input remains accepted for backward compatibility. An owner is
237	        // valid when it supplies an address in EITHER form (a non-blank addressLine1, or the flat
238	        // address). A whitespace-only value collapses to the empty string and counts as absent.
239	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
240	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
241	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
242	        boolean hasStructuredAddress = StringUtils.hasText(normalizedAddressLine1);
243	        boolean hasFlatAddress = StringUtils.hasText(normalizedFlatAddress);
244	        if (!hasStructuredAddress && !hasFlatAddress) {
245	            missingFields.add("address");
246	        }
247	        // Compose the stored/returned address: the structured lines when present (addressLine1, with a
248	        // single space and addressLine2 appended when addressLine2 is present), otherwise the flat form.
249	        String composedAddress;
250	        if (hasStructuredAddress) {
251	            composedAddress = StringUtils.hasText(normalizedAddressLine2)
252	                ? normalizedAddressLine1 + " " + normalizedAddressLine2
253	                : normalizedAddressLine1;
254	        } else {
255	            composedAddress = normalizedFlatAddress;
256	        }
257	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
258	            missingFields.add("city");
259	        }
260	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
261	            missingFields.add("telephone");
262	        }
263	        if (!missingFields.isEmpty()) {
264	            throw new InvalidRequestException(missingFields);
265	        }
266	        HttpHeaders headers = new HttpHeaders();
267	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
268	        // A newly created owner is never soft-deleted.
269	        owner.setDeleted(false);
270	        // Store (and later return) the normalized structured lines and the composed address. The
271	        // structured lines are kept only when the structured form was supplied; otherwise they are
272	        // cleared so the response reflects the flat form that was actually used.
273	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
274	        owner.setAddressLine2(hasStructuredAddress && StringUtils.hasText(normalizedAddressLine2)
275	            ? normalizedAddressLine2 : null);
276	        owner.setAddress(composedAddress);
277	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
278	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
279	        owner.setTelephone(normalizedTelephone);
280	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
281	        owner.setEmail(normalizeEmail(owner.getEmail()));
282	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
283	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
284	        validatePostcode(owner.getCity(), owner.getPostcode());
285	        // Reject a supplied registration date that lies in the future (later than the server's current
286	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
287	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
288	            throw new InvalidRequestException(List.of("registrationDate"));
289	        }
290	        // Default the (optional) registration date to the server's current date when none was supplied.
291	        if (owner.getRegistrationDate() == null) {
292	            owner.setRegistrationDate(LocalDate.now());
293	        }
294	        // The effective registration date must fall on a business day: when it lands on a Saturday,
295	        // Sunday or a listed public holiday (whether supplied or defaulted above), roll it forward to
296	        // the next non-holiday business day. Every value derived from the registration date below
297	        // (daily create-limit, membership number) uses this adjusted date.
298	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
299	        // Reject the request once the maximum number of owners for the owner's registration day has
300	        // been reached (100 or more owners already created on that date).
301	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
302	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
303	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
304	        }
305	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
306	        // owner's registration day at the moment this owner was created; otherwise clear it.
307	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
308	        // Reject the request when the owner's city has already reached its owner capacity.
309	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
310	            throw new CityCapacityException(owner.getCity());
311	        }
312	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
313	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
314	        // so any two owners with the same last name and postcode automatically resolve to the same
315	        // household without an explicit opt-in. It is assigned up front so it feeds the household-size
316	        // read-back, the membership-level cap and the household-of-3 points. It is NO LONGER part of
317	        // duplicate detection: that is expressed solely through the identity key below.
318	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
319	        owner.setHouseholdId(householdId);
320	        // All duplicate detection is consolidated into this single derived identity key: the SHA-256
321	        // hex of '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'. Reject with 409 only when
322	        // the new owner's WHOLE identity key exactly matches a non-deleted existing owner's. Because
323	        // the telephone is part of the key, two owners with the same last name and postcode but
324	        // different telephones have different keys and are both allowed (the second is a soft match,
325	        // see below); only an exact full-key match is a hard duplicate.
326	        String identityKey = owner.getIdentityKey();
327	        boolean identityCollision = this.clinicService.findAllOwners().stream()
328	            .filter(existing -> !existing.isDeleted())
329	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
330	        if (identityCollision) {
331	            throw new DuplicateIdentityException(identityKey);
332	        }
333	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
334	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
335	        // this owner's soundex(lastName) and postcode while carrying a DIFFERENT identity key. When
336	        // several existing owners match, the one with the lowest id is chosen so the result is
337	        // deterministic.
338	        Owner softMatch = findPossibleDuplicate(owner);
339	        if (softMatch != null) {
340	            owner.setPossibleDuplicate(true);
341	            owner.setPossibleDuplicateOf(softMatch.getId());
342	        } else {
343	            owner.setPossibleDuplicate(false);
344	        }
345	        // Record how many existing owners already share this first name and last name
346	        // (compared case-insensitively) before this owner is created.
347	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
348	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
349	        owner.setCustomerCode(generateCustomerCode(owner));
350	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
351	        // digits of the fiscal year the registration date falls in (e.g. 'NSW-1A2B3C4D-M27').
352	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
353	        this.clinicService.saveOwner(owner);
354	        // Remember the created owner under the request's idempotency key so a later create repeating
355	        // the same key returns this owner instead of creating a duplicate.
356	        if (idempotencyKey != null) {
357	            idempotencyKeyToOwnerId.put(idempotencyKey, owner.getId());
358	        }
359	        populateHouseholdSize(owner);
360	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
361	        // Cap the new owner's membership level at one above the current maximum among their
362	        // existing household members (no cap when the household has no other member).
363	        applyHouseholdMembershipCap(owner, ownerDto);
364	        // Emit an audit line carrying the new owner's id, customer code, registration date,
365	        // numeric membership level and membership number.
366	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
367	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
368	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
369	        headers.setLocation(UriComponentsBuilder.newInstance()
370	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
371	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
372	    }
373	
374	    /**
375	     * Return the current request's {@code Idempotency-Key} header value, or {@code null} when the
376	     * header is absent/blank or there is no bound servlet request.
377	     *
378	     * @return the trimmed idempotency key, or {@code null} when none was supplied
379	     */
380	    private String currentIdempotencyKey() {
381	        org.springframework.web.context.request.RequestAttributes attributes =
382	            org.springframework.web.context.request.RequestContextHolder.getRequestAttributes();
383	        if (attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes) {
384	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
385	            if (StringUtils.hasText(key)) {
386	                return key.trim();
387	            }
388	        }
389	        return null;
390	    }
