392	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
393	    @Override
394	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
395	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
396	        if (currentOwner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        currentOwner.setAddress(ownerFieldsDto.getAddress());
400	        currentOwner.setCity(ownerFieldsDto.getCity());
401	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
402	        currentOwner.setLastName(ownerFieldsDto.getLastName());
403	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
404	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
405	        this.clinicService.saveOwner(currentOwner);
406	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
407	    }
408	
409	    /**
410	     * Populate the owner's household size: the number of owners sharing this owner's
411	     * {@code householdId} (including the owner itself). An owner with no household is a household
412	     * of one.
413	     *
414	     * @param owner the owner whose household size should be computed and set
415	     */
416	    private void populateHouseholdSize(Owner owner) {
417	        String householdId = owner.getHouseholdId();
418	        if (!StringUtils.hasText(householdId)) {
419	            owner.setHouseholdSize(1);
420	            return;
421	        }
422	        int size = (int) this.clinicService.findAllOwners().stream()
423	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
424	            .count();
425	        owner.setHouseholdSize(size);
426	    }
427	
428	    /**
429	     * Cap the owner's membership level so it never exceeds one above the current maximum membership
430	     * level among the owner's household members (the other non-deleted owners sharing this owner's
431	     * {@code householdId}). When the household has no other member, no cap applies and the level is
432	     * left untouched. Any reduction is written back onto the given dto.
433	     *
434	     * @param owner    the owner whose household members bound the level (excluded from its own household)
435	     * @param ownerDto the mapped dto whose {@code membershipLevel} is capped in place
436	     */
437	    private void applyHouseholdMembershipCap(Owner owner, OwnerDto ownerDto) {
438	        String householdId = owner.getHouseholdId();
439	        if (!StringUtils.hasText(householdId) || ownerDto.getMembershipLevel() == null) {
440	            return;
441	        }
442	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
443	            .filter(existing -> !existing.isDeleted())
444	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
445	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
446	            .map(this::membershipLevelOf)
447	            .max(Integer::compareTo)
448	            .orElse(null);
449	        if (maxMemberLevel != null && ownerDto.getMembershipLevel() > maxMemberLevel + 1) {
450	            ownerDto.setMembershipLevel(maxMemberLevel + 1);
451	        }
452	    }
453	
454	    /**
455	     * Compute an existing household member's numeric membership level. The member's household size is
456	     * populated first so the level reflects the current household (the household-of-3 membership
457	     * points depend on it), then the mapper's derived {@code membershipLevel} is read back.
458	     *
459	     * @param member the household member to evaluate
460	     * @return the member's derived membership level
461	     */
462	    private int membershipLevelOf(Owner member) {
463	        populateHouseholdSize(member);
464	        return ownerMapper.toOwnerDto(member).getMembershipLevel();
465	    }
466	
467	    /**
468	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
469	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
470	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
471	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
472	     * longer any per-city sequence number.
473	     *
474	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
475	     * @return the generated (collision-free) customer code
476	     */
477	    private String generateCustomerCode(Owner owner) {
478	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
479	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
480	        String baseCode = region + "-" + hash8;
481	        return deduplicateCustomerCode(baseCode);
482	    }
483	
484	    /**
485	     * Return a customer code that does not collide with any existing owner's customer code. When the
486	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
487	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
488	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
489	     * persisted, so it never counts as a collision with itself.
490	     *
491	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
492	     * @return the de-duplicated customer code
493	     */
494	    private String deduplicateCustomerCode(String baseCode) {
495	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
496	            .map(Owner::getCustomerCode)
497	            .filter(java.util.Objects::nonNull)
498	            .collect(java.util.stream.Collectors.toSet());
499	        if (!existingCodes.contains(baseCode)) {
500	            return baseCode;
501	        }
502	        int n = 2;
503	        String candidate = baseCode + "-" + n;
504	        while (existingCodes.contains(candidate)) {
505	            n++;
506	            candidate = baseCode + "-" + n;
507	        }
508	        return candidate;
509	    }
510	
511	    /**
512	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
513	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
514	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
515	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
516	     * known region.
517	     *
518	     * @param postcode the owner's postcode, may be {@code null}
519	     * @param city     the owner's city
520	     * @return the derived region code
521	     */
522	    private String deriveRegion(String postcode, String city) {
523	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
524	            int value = Integer.parseInt(postcode);
525	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
526	                int[] range = entry.getValue();
527	                if (value >= range[0] && value <= range[1]) {
528	                    return entry.getKey();
529	                }
530	            }
531	        }
532	        String region = CITY_REGION.get(city);
533	        return region != null ? region : "UNKNOWN";
534	    }
535	
536	    /**
537	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
538	     * bytes of {@code input}.
539	     *
540	     * @param input  the value to digest
541	     * @param length the number of leading hex characters to return
542	     * @return the truncated upper-case hex digest
543	     */
544	    private String shortSha256Hex(String input, int length) {
545	        try {
546	            byte[] digest = MessageDigest.getInstance("SHA-256")
547	                .digest(input.getBytes(StandardCharsets.UTF_8));
548	            StringBuilder sb = new StringBuilder(digest.length * 2);
549	            for (byte b : digest) {
550	                sb.append(String.format("%02x", b));
551	            }
552	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
553	        } catch (java.security.NoSuchAlgorithmException e) {
554	            throw new IllegalStateException("SHA-256 not available", e);
555	        }
556	    }
557	
558	    /**
559	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
560	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
561	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
562	     * date that is stored, returned and used for every value derived from it.
563	     *
564	     * @param date the effective registration date (supplied or defaulted)
565	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
566	     */
567	    private LocalDate rollToBusinessDay(LocalDate date) {
568	        while (!isBusinessDay(date)) {
569	            date = date.plusDays(1);
570	        }
571	        return date;
572	    }
573	
574	    /**
575	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
576	     *
577	     * @param date the date to test
578	     * @return {@code true} when the date is a non-holiday weekday
579	     */
580	    private boolean isBusinessDay(LocalDate date) {
581	        DayOfWeek dayOfWeek = date.getDayOfWeek();
582	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
583	            return false;
584	        }
585	        return !PUBLIC_HOLIDAYS.contains(date);
586	    }
587	
588	    /**
589	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
590	     * last two digits of the fiscal year that the (business-day-adjusted) {@code registrationDate}
591	     * falls in (e.g. {@code SYD-SMI-0007-M27} for a registration in FY27).
592	     *
593	     * @param customerCode     the owner's already-assigned customer code
594	     * @param registrationDate the owner's business-day-adjusted registration date
595	     * @return the generated membership number
596	     */
597	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
598	        String yy = String.format("%02d", fiscalYear(registrationDate) % 100);
599	        return String.format("%s-M%s", customerCode, yy);
600	    }
601	
602	    /**
603	     * The fiscal year that the given date falls in. The fiscal year starts on 1 July, so a date in
604	     * July to December belongs to the fiscal year ending in the following calendar year, and a date
605	     * in January to June belongs to the fiscal year ending in the same calendar year. The fiscal
606	     * year is identified by that ending calendar year (e.g. 1 July 2026 to 30 June 2027 is 2027).
607	     *
608	     * @param date the date whose fiscal year is required
609	     * @return the fiscal year's ending calendar year
610	     */
611	    private int fiscalYear(LocalDate date) {
612	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
613	    }
614	
615	    /**
616	     * Count the existing owners that share the given first name and last name, comparing each
617	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
618	     * yet persisted, so it is not included in the count.
619	     *
620	     * @param firstName the incoming owner's first name
621	     * @param lastName  the incoming owner's last name
622	     * @return the number of existing namesakes
623	     */
624	    private int countNamesakes(String firstName, String lastName) {
625	        String normalizedFirstName = normalizeForComparison(firstName);
626	        String normalizedLastName = normalizeForComparison(lastName);
627	        return (int) this.clinicService.findAllOwners().stream()
628	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
629	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
630	            .count();
631	    }
632	
633	    /**
634	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
635	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
636	     *
637	     * @param city the incoming owner's city
638	     * @return the number of existing owners already in that city
639	     */
640	    private int countOwnersInCity(String city) {
641	        String normalizedCity = normalizeForComparison(city);
642	        return (int) this.clinicService.findAllOwners().stream()
643	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
644	            .count();
645	    }
646	
647	    /**
648	     * Count the existing owners whose registration date equals the given date. The incoming owner is
649	     * not yet persisted, so it is not included in the count.
650	     *
651	     * @param registrationDate the incoming owner's registration date
652	     * @return the number of existing owners already registered on that date
653	     */
654	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
655	        return (int) this.clinicService.findAllOwners().stream()
656	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
657	            .count();
658	    }
659	
660	    /**
661	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
662	     * shares the owner's {@code soundex(lastName)} and postcode while carrying a DIFFERENT identity
663	     * key. A blank postcode never soft-matches (postcode is required for the match). When several
664	     * owners match, the one with the lowest id is returned so the result is deterministic;
665	     * {@code null} when there is no soft match.
666	     *
667	     * @param owner the incoming owner (with normalized telephone, email and last name resolved)
668	     * @return the lowest-id matching existing owner, or {@code null} when none matches
669	     */
670	    private Owner findPossibleDuplicate(Owner owner) {
671	        if (!StringUtils.hasText(owner.getPostcode())) {
672	            return null;
673	        }
674	        String soundex = Owner.soundex(owner.getLastName());
675	        String identityKey = owner.getIdentityKey();
676	        return this.clinicService.findAllOwners().stream()
677	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
678	                && owner.getPostcode().equals(existing.getPostcode())
679	                && !identityKey.equals(existing.getIdentityKey()))
680	            .min(java.util.Comparator.comparing(Owner::getId))
681	            .orElse(null);
682	    }
683	
684	    /**
685	     * Generate the deterministic household identifier for the given last name and postcode. The value
686	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
687	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
688	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
689	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
690	     *
691	     * @param lastName the owner's last name
692	     * @param postcode the owner's postcode, may be {@code null}
693	     * @return the deterministic household identifier
694	     */
695	    private String generateHouseholdId(String lastName, String postcode) {
696	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
697	        return shortSha256Hex(key, 12);
698	    }
699	
700	    /**
701	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
702	     * single space, upper-case the result and expand common street-type abbreviations token by token
703	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
704	     * to the empty string. The result is the canonical form that is stored, returned and used for every
705	     * address comparison (household duplicate detection and the shared household id).
706	     *
707	     * @param address the raw address, may be {@code null}
708	     * @return the normalized address
709	     */
710	    private String normalizeAddress(String address) {
711	        if (address == null) {
712	            return "";
713	        }
714	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
715	        if (collapsed.isEmpty()) {
716	            return "";
717	        }
718	        String[] tokens = collapsed.split(" ");
719	        StringBuilder sb = new StringBuilder(collapsed.length());
720	        for (int i = 0; i < tokens.length; i++) {
721	            if (i > 0) {
722	                sb.append(' ');
723	            }
724	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
725	        }
726	        return sb.toString();
727	    }
728	
729	    /**
730	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
731	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
732	     *
733	     * @param value the raw value, may be {@code null}
734	     * @return the normalized value
735	     */
736	    private String normalizeForComparison(String value) {
737	        if (value == null) {
738	            return "";
739	        }
740	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
741	    }
742	
743	    /**
744	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
745	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
746	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
747	     * is returned lower-cased.
748	     *
749	     * @param email the raw email from the request payload, may be {@code null}
750	     * @return the lower-cased email, or {@code null} when none was provided
751	     */
752	    private String normalizeEmail(String email) {
753	        if (!StringUtils.hasText(email)) {
754	            return null;
755	        }
756	        if (!EMAIL_PATTERN.matcher(email).matches()) {
757	            throw new InvalidRequestException(List.of("email"));
758	        }
759	        String lowerCased = email.toLowerCase(Locale.ROOT);
760	        // Reject an address whose domain is on the disposable-domain blocklist.
761	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
762	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
763	            throw new InvalidRequestException(List.of("email"));
764	        }
765	        return lowerCased;
766	    }
767	
768	    /**
769	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
770	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
771	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
772	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
773	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
774	     * to 400 Bad Request).
775	     *
776	     * @param city     the owner's city (used to resolve the region)
777	     * @param postcode the raw postcode from the request payload, may be {@code null}
778	     */
779	    private void validatePostcode(String city, String postcode) {
780	        if (!StringUtils.hasText(postcode)) {
781	            return;
782	        }
783	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
784	            throw new InvalidRequestException(List.of("postcode"));
785	        }
786	        String region = CITY_REGION.get(city);
787	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
788	        if (range != null) {
789	            int value = Integer.parseInt(postcode);
790	            if (value < range[0] || value > range[1]) {
791	                throw new InvalidRequestException(List.of("postcode"));
792	            }
793	        }
794	    }
795	
796	    /**
797	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
798	     * already carries a leading '+' keeps its country code; otherwise the default country code
799	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
800	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
801	     * is thrown (mapped to 400 Bad Request).
802	     *
803	     * @param telephone the raw telephone from the request payload
804	     * @return the E.164 string (e.g. {@code +61412345678})
805	     */
806	    private String normalizeTelephone(String telephone) {
807	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
808	        String candidate;
809	        if (cleaned.startsWith("+")) {
810	            candidate = cleaned;
811	        } else {
812	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
813	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
814	        }
815	        if (!E164_PATTERN.matcher(candidate).matches()) {
816	            throw new InvalidRequestException(List.of("telephone"));
817	        }
818	        // For country codes with a known fixed national-number length, reject a candidate whose
819	        // national digits (everything after the '+' and the country code) do not match that length.
820	        String digits = candidate.substring(1);
821	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
822	            String countryCode = entry.getKey();
823	            if (digits.startsWith(countryCode)) {
824	                int nationalLength = digits.length() - countryCode.length();
825	                if (nationalLength != entry.getValue()) {
826	                    throw new InvalidRequestException(List.of("telephone"));
827	                }
828	                break;
829	            }
830	        }
831	        return candidate;
832	    }
833	
834	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
835	    @Transactional
836	    @Override
837	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
838	        Owner owner = this.clinicService.findOwnerById(ownerId);
839	        if (owner == null) {
840	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
841	        }
842	        // Soft delete: flag the owner deleted and retain the record rather than removing it. The
843	        // owner is still readable afterwards (with 'deleted' true) but is ignored by the create
844	        // endpoint's duplicate/identity checks.
845	        owner.setDeleted(true);
846	        this.clinicService.saveOwner(owner);
847	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
848	    }
849	
850	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
851	    @Override
852	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
853	        Owner owner = this.clinicService.findOwnerById(ownerId);
854	        if (owner == null) {
855	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
856	        }
857	        HttpHeaders headers = new HttpHeaders();
858	        Pet pet = petMapper.toPet(petFieldsDto);
859	        owner.setId(ownerId);
860	        pet.setOwner(owner);
861	        pet.getType().setName(null);
862	        this.clinicService.savePet(pet);
863	        PetDto petDto = petMapper.toPetDto(pet);
864	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
865	            .buildAndExpand(pet.getId()).toUri());
866	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
867	    }
868	
869	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
870	    @Override
871	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
872	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
873	        if (currentOwner != null) {
874	            Pet currentPet = this.clinicService.findPetById(petId);
875	            if (currentPet != null) {
876	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
877	                currentPet.setName(petFieldsDto.getName());
878	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
879	                this.clinicService.savePet(currentPet);
880	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
881	            }
882	        }
883	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
884	    }
885	
886	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
887	    @Override
888	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
889	        HttpHeaders headers = new HttpHeaders();
890	        Visit visit = visitMapper.toVisit(visitFieldsDto);
891	        Pet pet = new Pet();
892	        pet.setId(petId);
893	        visit.setPet(pet);
894	        this.clinicService.saveVisit(visit);
895	        VisitDto visitDto = visitMapper.toVisitDto(visit);
896	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
897	            .buildAndExpand(visit.getId()).toUri());
898	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
899	    }
900	
901	
902	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
903	    @Override
904	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
905	        Owner owner = this.clinicService.findOwnerById(ownerId);
906	        if (owner != null) {
907	            Pet pet = owner.getPet(petId);
908	            if (pet != null) {
909	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
910	            }
911	        }
912	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
913	    }
914	}
